    "privacyPage.privacyPolicy": "PRIVACY POLICY",
    "privacyPage.heroDescription": "Gaining and maintaining trust is essential to what we do. Learn how we protect your personal information.",
    "privacyPage.lastUpdated": "Last Updated: December 4, 2024",
    "privacyPage.generalInformation": "General Information on Privacy and Personal Data Protection",
    "privacyPage.generalInfoText1": "Gaining and maintaining trust is essential to what we do. Therefore, we are truly committed to transparency in our relationship and implementing practices that protect your personal data and other confidential information.",
    "privacyPage.generalInfoText2": "Hence, we invite you to engage in all our activities with complete confidence regarding the protection of your personal data and other confidential information. We do not collect any personal data without your explicit consent.",
    "privacyPage.generalInfoText3": "This document is a Privacy Policy and can help you find the necessary information about how we handle your personal data. Please carefully and thoroughly read this document to understand our practices.",
    "privacyPage.contactInfoController": "Contact Information for the Controller",
    "privacyPage.controllerText1": "Konti Hidroplast Dooel Gevgelija, in accordance with the Law on Personal Data Protection (Official Gazette of the Republic of North Macedonia No. 42/2020), acts as a controller for the processing of personal data.",
    "privacyPage.controllerText2": "You can contact us through multiple ways, including phone, email, live chat, or by mail. More details are available on our website:",
    "privacyPage.ourPostalAddress": "Our postal address is:",
    "privacyPage.dataProtectionOfficer": "Contact Details for the Data Protection Officer",
    "privacyPage.dpoText": "Our authorized Data Protection Officer can be contacted at",
    "privacyPage.howWeObtainInfo": "How do we obtain the information and personal data we process?",
    "privacyPage.obtainInfoText": "Most personal data and information we process is provided directly by you for one of the following reasons:",
    "privacyPage.accessProducts": "You choose to access our products, services, and resources.",
    "privacyPage.submitInquiry": "You submit an inquiry for information.",
    "privacyPage.applyJob": "You apply for a job with us.",
    "privacyPage.representOrganization": "You represent your organization during meetings and visits to our facilities.",
    "privacyPage.videoSurveillance": "Video Surveillance",
    "privacyPage.videoSurveillanceText1": "Konti Hidroplast Dooel Gevgelija, as a personal data controller, conducts video surveillance in its offices, warehouses, production facilities, and yard. During these activities, we may collect personal data.",
    "privacyPage.videoSurveillanceText2": "Typically, the personal data we collect is limited to the types of information usually found on a business card, which include, but are not limited to:",
    "privacyPage.firstLastName": "Your first and last name;",
    "privacyPage.jobTitle": "Your job title/position;",
    "privacyPage.companyName": "The name of the company/institution you work for (not personal data per se);",
    "privacyPage.workEmail": "Your work email address;",
    "privacyPage.phoneNumber": "Your phone number.",
    "privacyPage.websiteBrowsing": "Information collected during website browsing",
    "privacyPage.websiteBrowsingText": "In addition to the information you choose to provide us, we also collect the following technical information, which, under certain conditions, may be considered personal data:",
    "privacyPage.ipAddresses": "IP addresses and/or domain names of computers used to access our services;",
    "privacyPage.uriAddresses": "URI (Uniform Resource Identifier) addresses of resources requested by your browser;",
    "privacyPage.timeRequest": "Time of request;",
