    "privacyPage.fileSize": "Size of the file received as a response;",
    "privacyPage.responseStatus": "Numerical code indicating the response status of the server (success, error, etc.);",
    "privacyPage.operatingSystem": "Parameters related to the operating system you use.",
    "privacyPage.useAndSharing": "Use and sharing of your personal data",
    "privacyPage.useAndSharingText1": "All personal data you provide us is used for delivering the highest quality of our services and information as outlined in this document. We never sell, rent, or trade your personal data.",
    "privacyPage.useAndSharingText2": "Currently, we do not share your personal data with third parties. However, we may plan to use third-party services in the future to send you information about our products and services.",
    "privacyPage.useAndSharingText3": "Personal data obtained during the use of our services is used solely for collecting anonymous statistical information about our website and for verifying the proper functioning of our services.",
    "privacyPage.yourRights": "Your rights regarding personal data protection",
    "privacyPage.rightsText": "According to the Law on Personal Data Protection, you have specific rights depending on the purpose and reason for processing your data. Below are the key rights you have:",
    "privacyPage.right1Title": "1. Right of Access",
    "privacyPage.right1Text": "You can request copies of your personal data at any time, subject to legal exceptions.",
    "privacyPage.right2Title": "2. Right of Rectification",
    "privacyPage.right2Text": "You can request corrections of inaccurate or incomplete data.",
    "privacyPage.right3Title": "3. Right of Erasure",
    "privacyPage.right3Text": "Under certain conditions, you can request deletion of your personal data.",
    "privacyPage.right4Title": "4. Right to Restrict Processing",
    "privacyPage.right4Text": "You can request restricted processing of your data under certain conditions.",
    "privacyPage.right5Title": "5. Right to Object",
    "privacyPage.right5Text": "You can object to data processing if it doesn't fall under our legal obligations or legitimate interests.",
    "privacyPage.right6Title": "6. Right to Data Portability",
    "privacyPage.right6Text": "You can request your data to be transferred to another organization or provided directly to you.",
    "privacyPage.right7Title": "7. Right to Complain",
    "privacyPage.right7Text": "If you are dissatisfied, you can file a complaint with the Personal Data Protection Agency at",
