    // Privacy Policy Page - Macedonian
    "privacyPage.backToHome": "Назад на почетна",
    "privacyPage.privacySecurity": "ПРИВАТНОСТ И БЕЗБЕДНОСТ",
    "privacyPage.privacyPolicy": "ПОЛИТИКА ЗА ПРИВАТНОСТ",
    "privacyPage.heroDescription": "Заработувањето и одржувањето на доверба е суштинско за она што го правиме. Дознајте како ја заштитуваме вашата лична информација.",
    "privacyPage.lastUpdated": "Последно ажурирано: 4 декември 2024",
    "privacyPage.generalInformation": "Општи информации за приватност и заштита на лични податоци",
    "privacyPage.generalInfoText1": "Заработувањето и одржувањето на доверба е суштинско за она што го правиме. Затоа, навистина сме посветени на транспарентност во нашата врска и спроведување на практики за приватност. Секоја лична информација и податоци што ни се откриваат и се сметаат за лични податоци ќе се обработуваат само ако постои правна основа за тоа - конкретно за дефинирана намена и со вашата согласност каде што е потребно.",
    "privacyPage.generalInfoText2": "Оттука, ве покануваме да се вклучите во сите наши активности со целосна доверба во однос на заштитата на вашите лични податоци и други доверливи информации. Не собираме лична информација или податоци од деца.",
    "privacyPage.generalInfoText3": "Овој документ е Политика за приватност и може да ви помогне да ги најдете потребните информации за тоа како ги ракуваме вашите лични податоци. Ве молиме внимателно и темелно прочитајте го документот за подобро да разберете какви лични податоци собираме, како ги собираме, за каква намена ги користиме, со кого ги споделуваме, колку долго ги чуваме и на кого ги откриваме вашите лични податоци. Нашата Политика за приватност редовно ќе се ажурира или менува според нашите активности и потреби, и ќе бидете известувани навремено.",
    "privacyPage.contactInfoController": "Контакт информации за контролорот",
    "privacyPage.controllerText1": "Конти Хидропласт Дооел Гевгелија, во согласност со Законот за заштита на лични податоци (Службен весник на Република Северна Македонија бр. 42/2020), дејствува како контролор на личните податоци што ги обработуваме, освен ако не е поинаку наведено во овој документ.",
    "privacyPage.controllerText2": "Можете да не контактирате преку повеќе начини, вклучувајќи телефон, е-пошта, жив разговор или по пошта. Повеќе детали се достапни на нашата веб-страница:",
    "privacyPage.ourPostalAddress": "Нашата поштенска адреса е:",
    "privacyPage.dataProtectionOfficer": "Контакт детали за службеникот за заштита на податоци",
    "privacyPage.dpoText": "Нашиот овластен службеник за заштита на податоци може да се контактира на",
    "privacyPage.howWeObtainInfo": "Како ги добиваме информациите и личните податоци што ги обработуваме?",
    "privacyPage.obtainInfoText": "Повеќето лични податоци и информации што ги обработуваме се обезбедени директно од вас поради една од следниве причини:",
    "privacyPage.accessProducts": "Избирате да пристапите до нашите производи, услуги и ресурси.",
    "privacyPage.submitInquiry": "Поднесувате барање за информации.",
    "privacyPage.applyJob": "Аплицирате за работа кај нас.",
    "privacyPage.representOrganization": "Претставувате ја вашата организација за време на средби и посети на нашите простории.",
    "privacyPage.videoSurveillance": "Видео надзор",
    "privacyPage.videoSurveillanceText1": "Конти Хидропласт Дооел Гевгелија, како контролор на лични податоци, врши видео надзор во своите канцеларии, магацини, производствени објекти и двор. За време на овој процес, физичките и физиолошките карактеристики се обработуваат во форма на снимки на вработени и посетители во Конти Хидропласт. Повеќе детали за намените на видео надзорот и категориите на лични податоци што се обработуваат може да се најдат на нашата веб-страница во Изјавата за приватност за видео надзор.",
    "privacyPage.videoSurveillanceText2": "Типично, личните податоци што ги собираме се ограничени на типовите информации што обично се наоѓаат на визитка, кои вклучуваат, но не се ограничени на:",
    "privacyPage.firstLastName": "Вашето име и презиме;",
