    "privacyPage.operatingSystem": "Параметри поврзани со оперативниот систем што го користите.",
    "privacyPage.useAndSharing": "Користење и споделување на вашите лични податоци",
    "privacyPage.useAndSharingText1": "Сите лични податоци што ни ги обезбедувате се користат за испорака на највисок квалитет на нашите услуги и информации како што е наведено во овој документ. Никогаш нема да ги продадеме вашите лични податоци на никого, ниту ќе ги споделиме без овластување.",
    "privacyPage.useAndSharingText2": "Во моментов, не ги споделуваме вашите лични податоци со трети страни. Сепак, може да планираме да користиме услуги на трети страни во иднина за да ви испратиме информации за нашите активности, работни планови, прегледи на производи, итн., под услов да се согласивте со тоа. Ова ќе биде дел од ажурирана Политика за приватност и ќе бидете известувани преку најава на нашата веб-страница.",
    "privacyPage.useAndSharingText3": "Личните податоци добиени за време на користењето на нашите услуги се користат единствено за собирање анонимни статистички информации за нашата веб-страница и за верификација на нејзиното правилно функционирање и подобрување на квалитетот на нашите услуги. Овие податоци се бришат веднаш по обработката.",
    "privacyPage.yourRights": "Вашите права во однос на заштитата на личните податоци",
    "privacyPage.rightsText": "Според Законот за заштита на лични податоци, имате специфични права во зависност од намената и причината за обработка на вашите податоци. Подолу се клучните права на кои имате право:",
    "privacyPage.right1Title": "1. Право на пристап",
    "privacyPage.right1Text": "Можете да побарате копии од вашите лични податоци во секое време, под правни исклучоци.",
    "privacyPage.right2Title": "2. Право на поправка",
