    "aboutUs.getInTouchTitle": "Стапете во контакт: Поврзете се со нас денес!",
    "aboutUs.getInTouchDescription": "Треба ви повеќе информации за нашите решенија за заштита на кабли? Контактирајте го нашиот тим на експерти.",
    "aboutUs.englishLang": "🇺🇸 Англиски",
