    // Products Pages
    "productsPage.heroHighQualityPipes": "ВИСОКО-КВАЛИТЕТНИ ЦЕВКИ",
    "productsPage.heroManufacturingExcellence": "Производна извонредност",
    "productsPage.heroIsoCertified": "ИСО сертифицирано",
    "productsPage.heroImageAlt": "Високо-квалитетни ПЕ и ПП системи за цевки во производствен објект",
    "productsPage.heroDrivingProgress": "Движејќи напредок со иновации",
    "productsPage.productRange": "Опсег на производи",
    "productsPage.applicationDescription1": "Производите на Конти Хидропласт наоѓаат широк опсег на примени во индустрискиот и комуналниот пазар на светско ниво. Претпријатијата за дистрибуција на вода и гас се важни сектори за производи со висок интегритет каде што одржувањето на квалитетот на водата и безбедниот транспорт на гасовити горива се од пресудна важност.",
    "productsPage.applicationDescription2": "Индустриските примени вклучуваат инсталации за алтернативна енергија во системи за депониски гас до транспорт на отпадни води и минерални суспензии. Производите се широко користат во инсталација, поправка и одржување на цевководи.",
    "productsPage.peTechnicalAlt": "Дијаграм за технички спецификации на ПЕ цевки",
    "productsPage.peFlowAlt": "Дијаграм за технички спецификации на ПЕ проток",
    "productsPage.metaDescription": "Истражете го нашиот сеопфатен асортиман на ПЕ и ПП цевки за водоснабдување, канализација, системи за гасоводи и заштита на кабли. Квалитетни производи кои ги исполнуваат меѓународните стандарди.",
    
    // Superlit GRP Products
