    "ctpPipes.tab3TechTitle": "Технички спецификации за CTP цевки",
    "ctpPipes.tab3FlowTitle": "Брзина на проток",
    "ctpPipes.tab3FlowText": "Препорачана брзина на проток за стандардни CTP цевки е макс. 4 m/s. Со специјален дизајн можат да се проектираат цевки за поголеми брзини.",
    "ctpPipes.tab3CoefTitle": "Коефициент на проток",
    "ctpPipes.tab3CoefText": "Вредности за хидраулични пресметки со SUPERLIT CTP цевки:\nХејзен-Вилијамс коефициент: C = 150\nМанинг коефициент: n = 0,009\nColebrook-White коефициент:\n- Континуирано навивање: k = 0,029 mm\n- Центрифугално леење: k = 0,012 mm",
    "ctpPipes.tab3UVTitle": "UV отпорност",
    "ctpPipes.tab3UVText": "Перформансите на CTP цевките не се негативно засегнати од UV зрачење. Промените на бојата на површината кои не влијаат на јачината се нормални.",
    "ctpPipes.tab3PoissonTitle": "Поасонов однос",
    "ctpPipes.tab3PoissonText": "Поасоновиот однос за инженерски пресметки за стандардни CTP цевки е помеѓу 0,22 - 0,29.",
    "ctpPipes.tab3TempTitle": "Температура",
    "ctpPipes.tab3TempText": "Работната температура на стандардни CTP цевки е помеѓу -40°C и +35°C. Достапен е специјален дизајн за работни температури до 50°C.",
    "ctpPipes.tab3ThermalTitle": "Коефициент на термална експанзија",
    "ctpPipes.tab3ThermalText": "Аксијалниот коефициент на термална експанзија на SUPERLIT CTP цевки е во опсег од 24 до 30 x (1/10⁶) mm/mm/°C.",
