    // CTP Fittings Page
    "ctpFittings.pageTitle": "Спојни елементи (Fittings)",
    "ctpFittings.metaDescription": "SUPERLIT CTP Спојни елементи - Тее делови, колена, прирабници и редукции за GRP/CTP цевоводни системи.",
    "ctpFittings.heroBadge": "CTP СПОЈНИ ЕЛЕМЕНТИ",
    "ctpFittings.heroTitle": "Bağlantı Parçaları",
    "ctpFittings.heroDescription": "SUPERLIT CTP спојните елементи обезбедуваат супериорни решенија за доверливост и перформанси во вашите цевоводни системи. Произведени од материјал од стаклени влакна армиран полиестер (CTP), овие спојни елементи се истакнуваат со висока јачина, отпорност на корозија и долг животен век.",
    "ctpFittings.heroFeature1": "Висока јачина",
    "ctpFittings.heroFeature2": "Отпорност на корозија",
    "ctpFittings.heroFeature3": "Долг животен век",
