    // Konti Kan Duct Cable Protection
    "cableProtection.ductDescription": "Полиетиленските цевки со мал дијаметар се користат за инсталирање кабелска канализација, за подземно поставување. Главно се користат како заштита за оптички кабли, коаксијални оптички кабли за дистрибутивни системи и други функционални мрежи. Исто така се користат за класични телекомуникациски кабли со помал дијаметар. Нивната надворешна површина е мазна со надолжно ребеста внатрешност, и се произведуваат во калемови до 500 м.",
