    // Konti Kan Optic Cable Protection
    "cableProtection.opticDescription": "Овие HDPE цевки се користат за заштита или држачи на заштитните цевки, особено за поминување на патишта и мостови. Тие се двостени цевки со мазна внатрешност и валовита надворешна површина. Цевки со поголеми дијаметри што се користат за вметнување на сноп цевки за заштита на оптички кабли и за поминување на патишта или мостови. Се произведуваат во црна, црвена и жолта боја, но и во секоја специјална боја побарана од купувачот.",
