    "ctpFittings.tab2Label": "BÖGEN",
    "ctpFittings.tab3Label": "FLANSCHE",
    "ctpFittings.tab4Label": "REDUZIERSTÜCKE",
    "ctpFittings.equalTees": "Gleiche T-Stücke",
