    // Konti Kan Duct Cable Protection
    "cableProtection.ductDescription": "Die Polyethylenrohre mit kleinem Durchmesser werden für die Installation von Kabelkanalisationen für unterirdische Verlegung verwendet. Hauptsächlich werden sie als Schutz für Glasfaserkabel, koaxiale Glasfaserkabel für Verteilungssysteme und andere funktionale Netze verwendet. Sie werden auch für klassische Telekommunikationskabel mit kleinerem Durchmesser verwendet. Ihre Außenfläche ist glatt mit längsgerippter Innenseite und sie werden in Rollen bis zu 500 m hergestellt.",
