    // Konti Kan Optic Cable Protection
    "cableProtection.opticDescription": "Diese HDPE-Rohre werden zum Schutz oder als Halter für die Schutzrohre verwendet, insbesondere für Straßen- und Brückendurchführungen. Es sind doppelwandige Rohre mit glattem Innenraum und gewellter Außenfläche. Rohre mit größeren Durchmessern, die für das Einführen von Rohrbündeln zum Schutz von Glasfaserkabeln und für Straßen- oder Brückendurchführungen verwendet werden. Sie werden in schwarzer, roter und gelber Farbe hergestellt, aber auch in jeder vom Kunden gewünschten Sonderfarbe.",
