    "spiralPipes.hdpeId": "HDPE / ID",
    "spiralPipes.heroDescription": "Kunden und Ingenieure erkennen Polyethylen als ideales Rohrmaterial für viele Druck- und drucklose Anwendungen wie Wasserverteilung, Schwerkraftkanalisation, Sanierungsprojekte und Schächte.",
