    "ppMlCompact.pipe": "ROHR",
    "ppMlCompact.heroDescription": "PP ML (Polypropylen Multi-Layer) Vollrohre sind speziell für Abwasser- und Entwässerungssysteme entwickelt und bieten eine Kombination aus Langlebigkeit, Effizienz und Umweltverträglichkeit.",
