    "ppMlCompact.technicalSpecifications": "Technische Spezifikationen",
    "ppMlCompact.mainDescription": "PP ML Kompaktrohr besteht aus hochmoduligem Polypropylen (PP-HM) als Grundmaterial mit drei Schichten. Jede der drei Schichten hat eine unterschiedliche modifizierte Formel des Grundmaterials, was spezifische Leistungen in der Gesamtqualität des Rohrs verleiht.",
    "ppMlCompact.productionStandard": "Produktionsstandard: EN 13476-2:2007 (Typ А1) und ONR 201513:2011",
    "ppMlCompact.tripleLayeredPipe": "DREISCHICHTIGES ROHR",
    "ppMlCompact.tripleLayerDescription": "PP ML (dreischichtige) Vollrohre bieten eine robuste, effiziente und umweltfreundliche Lösung für moderne Abwassersysteme. Ihre Kombination aus struktureller Festigkeit, hydraulischer Leistung und chemischer Beständigkeit macht sie ideal für kommunale und industrielle Abwasseranwendungen.",
    
