    "ppMlCompact.middleLayer": "MITTELSCHICHT:",
    "ppMlCompact.middleLayerDescription": "Schlagzähe Schicht, auch bei niedrigen Temperaturen.",
    "ppMlCompact.outerLayer": "AUSSENSCHICHT:",
    "ppMlCompact.outerLayerDescription": "Aus hochwertigem PP, gefüllt mit mineralischem Modifikator; hochbeständig gegen Witterungseinflüsse und Oberflächenschäden. Die modifizierte PP-Formel gewährleistet hohen UV-Schutz und ermöglicht Außenlagerung.",
    
